import numpy as np

W1 = W['W1']

def get_map(c, j):
    M = np.zeros((8, 8))
    for r in range(8):
        for col in range(8):
            idx = ((r + 1) * 10 + (col + 1)) * 5 + c
            M[r, col] = W1[idx, j]
    return M.flatten()

pairs = [(0, 1), (0, 2), (1, 2), (0, 4), (1, 4)]

for c1, c2 in pairs:
    corrs = []
    for j in range(32):
        a = get_map(c1, j)
        b = get_map(c2, j)
        if np.std(a) == 0 or np.std(b) == 0:
            corrs.append(np.nan)
        else:
            corrs.append(np.corrcoef(a, b)[0, 1])
    corrs = np.array(corrs)
    print(f"CH{c1}-CH{c2}: mean={np.nanmean(corrs):.3f}, "
          f"max={np.nanmax(corrs):.3f}, min={np.nanmin(corrs):.3f}, "
          f"frac>0.5={np.nanmean(corrs > 0.5):.3f}, "
          f"frac<-0.5={np.nanmean(corrs < -0.5):.3f}")
    idx = np.argsort(-np.abs(corrs))[:5]
    print("  top:", [(int(j), round(float(corrs[j]), 3)) for j in idx])

import numpy as np
W1, W2, W3 = W['W1'], W['W2'], W['W3']
