eff = W1 @ W2 @ W3  # 500 x 5

channels = [0, 1, 2, 4]
maps = {}
for ch in channels:
    arr = np.zeros((8, 8, 5))
    for i, r in enumerate(range(1, 9)):
        for j, c in enumerate(range(1, 9)):
            idx = (r * 10 + c) * 5 + ch
            arr[i, j] = eff[idx]
    maps[ch] = arr

norms = {ch: np.linalg.norm(maps[ch], axis=2) for ch in channels}

def corr(a, b):
    return np.corrcoef(a.flatten(), b.flatten())[0, 1]

print("Norm map correlations:")
for ch1 in channels:
    for ch2 in channels:
        if ch1 < ch2:
            print(f"CH{ch1}-CH{ch2}: {corr(norms[ch1], norms[ch2]):.3f}")

